body,html{overflow-x:hidden}.logo,body{color:var(--text)}.orb,.status-dot{border-radius:50%}body,button{font-family:Inter,sans-serif}.bar,button{cursor:pointer;touch-action:manipulation}.footer,.hero,.toast{text-align:center}:root{--text:#f5f5f7;--muted:#858591}body,html{width:100%}body{min-height:100vh;background:#000;font-size:14px;-webkit-text-size-adjust:100%}.background{position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:-1}.orb{position:absolute;width:350px;height:350px;filter:blur(100px);opacity:.12;animation:10s ease-in-out infinite alternate float}.bar-tooltip,.toast{left:50%;opacity:0;pointer-events:none}.orb.one{background:#795cff;top:-120px;left:-100px}.orb.two{background:#386bff;right:-130px;bottom:-120px;animation-delay:-4s}@keyframes float{to{transform:translate(60px,40px) scale(1.12)}}.navbar{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 5%;border-bottom:1px solid rgba(255,255,255,.05);background:rgba(0,0,0,.92);backdrop-filter:blur(20px);position:sticky;top:0;z-index:50}.logo,.nav-right{align-items:center;display:flex}.bar,.chart-wrap{position:relative}.logo{gap:10px;font-size:17px;font-weight:700;cursor:pointer;text-decoration:none}.badge,.status{font-size:11px}.logo span{color:#a994ff}.card .label,.hero p,.page-head p{color:var(--muted)}.nav-right{gap:14px}.status{display:flex;align-items:center;gap:8px;color:#777782}.status-dot{width:7px;height:7px;background:#72e6a2;box-shadow:0 0 10px #72e6a2}.badge,button{background:rgba(255,255,255,.035);font-weight:600}.view{display:none}.view.active{display:block;animation:.25s fadeIn}@keyframes fadeIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}.container{width:min(1180px,94%);margin:auto;padding:36px 0 50px}.hero{padding:50px 0 30px}.badge{display:inline-flex;padding:7px 13px;border:1px solid rgba(255,255,255,.1);border-radius:100px;color:#d0d0d0;margin-bottom:18px}.hero h1{font-size:clamp(28px,7vw,58px);line-height:1.08;letter-spacing:-1.5px;margin-bottom:16px}.hero h1 span{background:linear-gradient(90deg,#fff,#a994ff);-webkit-background-clip:text;background-clip:text;color:transparent}.hero p{max-width:560px;margin:0 auto 30px;line-height:1.7;font-size:14px;padding:0 6px}.hero-actions{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;padding:0 6px}button{height:44px;padding:0 20px;border-radius:11px;border:1px solid rgba(255,255,255,.12);color:#e5e5ea;font-size:13px;transition:.2s}button:hover{transform:translateY(-1px);background:rgba(255,255,255,.08)}button:active{transform:scale(.97)}button:disabled{opacity:.45;cursor:not-allowed;transform:none}.btn-obfuscate{background:#000;color:#fff;border:1px solid #fff;padding:0 26px;box-shadow:0 8px 25px rgba(255,255,255,.08)}.btn-obfuscate:hover{background:#111}.btn-ghost,textarea{background:0 0}.card,.chart-container{background:rgba(0,0,0,.94)}.btn-back{height:38px;font-size:12px;padding:0 14px}.page-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:24px;flex-wrap:wrap}.page-head h2{font-size:clamp(22px,5vw,28px);letter-spacing:-1px}.page-head p{font-size:12px;margin-top:6px;line-height:1.5}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}.card{border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:16px}.card .label{font-size:10px;text-transform:uppercase;letter-spacing:.8px;margin-bottom:10px;font-weight:600}.card .value{font-size:clamp(20px,5vw,26px);font-weight:700;letter-spacing:-.5px}.card .sub{color:#66666f;font-size:10px;margin-top:5px}.chart-container{border:1px solid rgba(255,255,255,.08);border-radius:16px;padding:16px;margin-top:20px;overflow:hidden}.chart-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;gap:10px;flex-wrap:wrap}.chart-header h3{font-size:14px;font-weight:600;color:#e5e5ea}.chart-legend{display:flex;gap:14px;font-size:11px;color:#858591}.legend-item{display:flex;align-items:center;gap:6px}.chart-labels,.chart-wrap{gap:3px;min-width:100%;display:flex}.legend-color{width:10px;height:10px;border-radius:3px}.legend-sync{background:#72e6a2}.legend-unc{background:#795cff}.chart-scroll{overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;padding-bottom:6px;scrollbar-width:thin;scrollbar-color:#333 transparent}.chart-scroll::-webkit-scrollbar{height:6px}.chart-scroll::-webkit-scrollbar-track{background:0 0}.chart-scroll::-webkit-scrollbar-thumb{background:#333;border-radius:3px}.chart-wrap{height:180px;align-items:flex-end}.bar{flex:0 0 auto;width:8px;border-radius:3px 3px 0 0;transition:height .3s;min-height:3px}.bar.sync{background:linear-gradient(180deg,#72e6a2,#3aad6e)}.bar.unc{background:linear-gradient(180deg,#795cff,#4a35b5)}.bar.active,.bar:hover{opacity:.85;filter:brightness(1.15)}.bar-tooltip{position:absolute;bottom:100%;transform:translateX(-50%);background:rgba(15,15,20,.98);border:1px solid rgba(255,255,255,.12);padding:5px 8px;border-radius:7px;font-size:10px;color:#ddd;white-space:nowrap;transition:.15s;margin-bottom:6px;z-index:10;font-weight:500}.bar.active .bar-tooltip,.bar:hover .bar-tooltip{opacity:1}.chart-labels{padding:8px 0 0;font-size:9px;color:#55555f}.chart-labels span{flex:0 0 auto;width:8px;text-align:center;overflow:visible;font-size:9px}.chart-footer{display:flex;justify-content:space-between;margin-top:10px;font-size:10px;color:#55555f;padding:0 2px}.editor-wrapper{border:1px solid rgba(255,255,255,.08);border-radius:16px;background:rgba(0,0,0,.94);backdrop-filter:blur(25px);box-shadow:0 25px 80px rgba(0,0,0,.35);overflow:hidden}.editor-top{height:46px;padding:0 14px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.06)}.window-dots{display:flex;gap:6px}.window-dots i{width:8px;height:8px;border-radius:50%;background:#303038}.editor-title{color:#74747f;font-size:11px}.editors{display:grid;grid-template-columns:1fr 1fr}.editor+.editor{border-left:1px solid rgba(255,255,255,.06)}.editor-label{height:42px;padding:0 14px;display:flex;align-items:center;justify-content:space-between;color:#9999a4;font-size:11px;border-bottom:1px solid rgba(255,255,255,.045)}.label-left{display:flex;align-items:center;gap:8px}.lua-dot{width:6px;height:6px;border-radius:50%;background:#fff;box-shadow:0 0 8px rgba(255,255,255,.3)}textarea{display:block;width:100%;height:340px;resize:none;outline:0;border:0;padding:16px;color:#d8d8df;font-family:"Courier New",monospace;font-size:13px;line-height:1.7;-webkit-appearance:none}textarea::placeholder{color:#44444e}.output{color:#b9b2d7}.editor-bottom{min-height:64px;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px;border-top:1px solid rgba(255,255,255,.06);flex-wrap:wrap}.stats{color:#656570;font-size:11px}.actions{display:flex;gap:8px;flex-wrap:wrap}.toast{position:fixed;bottom:20px;transform:translate(-50%,20px);padding:11px 16px;border-radius:10px;background:rgba(0,0,0,.97);border:1px solid rgba(255,255,255,.09);color:#ddd;font-size:12px;transition:.25s;z-index:100;max-width:90vw}.toast.show{opacity:1;transform:translate(-50%,0)}.footer{margin-top:26px;color:#44444d;font-size:10px;padding:0 12px}.features{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin-top:36px;max-width:900px;margin-left:auto;margin-right:auto}.feature{border:1px solid rgba(255,255,255,.06);border-radius:12px;padding:16px;background:rgba(255,255,255,.02);text-align:left}.feature h4{font-size:13px;margin-bottom:6px;color:#e5e5ea}.feature p{font-size:11px;color:var(--muted);line-height:1.5}@media(max-width:820px){.cards,.hero-actions{gap:10px}.status{display:none}.container{width:96%;padding:24px 0 40px}.hero{padding:36px 0 24px}.card,.chart-container,textarea{padding:14px}.hero p{font-size:13px}.hero-actions button{flex:1;min-width:130px}.cards{grid-template-columns:1fr 1fr}.card .value{font-size:20px}.chart-wrap{height:160px}.bar,.chart-labels span{width:7px}.chart-labels,.chart-wrap{gap:2px}.editors{grid-template-columns:1fr}.editor+.editor{border-left:0;border-top:1px solid rgba(255,255,255,.06)}textarea{height:220px;font-size:12px}.editor-bottom{flex-direction:column;align-items:stretch;gap:10px}.stats{text-align:center;font-size:10px}.actions{width:100%;gap:8px}.actions button{flex:1;min-width:0;padding:0 10px;font-size:12px;height:42px}}@media(max-width:400px){.cards{grid-template-columns:1fr}.hero-actions button{flex:1 1 100%}.bar,.chart-labels span{width:6px}.actions button{font-size:11px;padding:0 8px}}
